<?php
namespace App\Modules\Scheduling\Notifications;
use App\Modules\Scheduling\Models\Appointment; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
final class AppointmentReminderNotification extends Notification implements ShouldQueue {use Queueable; public function __construct(public Appointment $appointment,public int $minutesBefore,public string $expectedStart){} public function via(object $notifiable):array{$this->appointment->refresh();return in_array($this->appointment->status,['scheduled','confirmed'],true)&&$this->appointment->scheduled_start_at->utc()->toIso8601String()===$this->expectedStart?['mail']:[];} public function toMail(object $notifiable):MailMessage{$a=$this->appointment->loadMissing('eventType');return(new MailMessage)->subject('Lembrete de agendamento')->line($a->eventType->name)->line($a->scheduled_start_at->setTimezone($a->timezone)->format('d/m/Y H:i').' ('.$a->timezone.')')->action('Ver detalhes',route('scheduling.public.confirmation',$a));}}
